-- A sheet's settings, one value per key (clerk-limit: a two-decimal amount; null: no limit). A key with no row
-- has no value.
CREATE TABLE setting (
    sheet_id    VARCHAR(200) NOT NULL,
    setting_key VARCHAR(50)  NOT NULL,
    setting_value VARCHAR(50),
    PRIMARY KEY (sheet_id, setting_key)
);

-- The role a user name has on a sheet: clerk or steward. A name with no row is a clerk.
CREATE TABLE user_role (
    sheet_id  VARCHAR(200) NOT NULL,
    user_name VARCHAR(200) NOT NULL,
    role      VARCHAR(20)  NOT NULL,
    PRIMARY KEY (sheet_id, user_name)
);
-- Every role given on a sheet, in the order given, with the sheet's today when it was given, so the role a user had
-- as of a date can be read. A user with a role but no line here had it from the beginning.
CREATE TABLE user_role_log (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(200) NOT NULL,
    user_name VARCHAR(200) NOT NULL,
    role      VARCHAR(20)  NOT NULL,
    set_on    DATE         NOT NULL
);
CREATE INDEX user_role_log_sheet ON user_role_log (sheet_id, user_name, id);
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { peopleKey } from '../people/people';
import { sum } from '../rates/rates';

/** A member of a crew: the person's `personId` and `name`. */
export type CrewMember = { personId: number; name: string };

/** A crew of the sheet: its `name` (trimmed, unique on the sheet), its lead (`leadId`, `lead` their name; null and blank once the lead has left the sheet) and its
 *  members in the order added (never the lead, a person at most once). A person can be in several crews. */
export type Crew = { name: string; leadId: number | null; lead: string; members: CrewMember[] };

/** Under the people's key, so every change to a person (a rename or merge above all) reloads the crews. */
export const crewsKey = (sheetId: string) => [...peopleKey(sheetId), 'crews'];

/** The sheet's crews, in the order added. */
export function useCrews(sheetId: string) {
  return useQuery({
    queryKey: crewsKey(sheetId),
    queryFn: () => getJson<Crew[]>(`/api/sheets/${encodeURIComponent(sheetId)}/crews`),
  });
}

/** A crew's due-total: its lead's and its members' due-totals (as their rows show them) added up, skipping n/a. */
export function crewDueTotal(crew: Crew, due: Map<number, string>): string {
  return sum([...(crew.leadId === null ? [] : [crew.leadId]), ...crew.members.map((m) => m.personId)].map((id) => due.get(id) ?? 'n/a'));
}
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HttpError, postJson, putJson } from '../../api/http';
import { PeopleHead, PersonRow } from '../../slots/defs/personRow';
import { SheetPage } from '../../slots/defs/sheetPage';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { claimsKey, type Claim } from '../claims/claims';
import { tagsKey } from '../tags/tags';
import { usePeopleDue } from '../header/totals';
import { GRADES, peopleKey, shownName, SORT_KEYS, sortPeople, useEditingPerson, usePeople, useShowRetired, useSortBy, type Person } from './people';
import { useShownColumns } from '../columns/columns';

/** The form's values. `gradeFrom` (yyyy-MM-dd) is the date the grade is given from; blank, the sheet's today. A
 *  person's first grade applies from the beginning of time. `terms` are the person's own terms in days; blank, none. `termsFrom` (yyyy-MM-dd) is the date they are given from;
 *  blank, the beginning of time. `contact` is the person's contact, kept by the server
 *  without surrounding spaces and lower-cased; blank, none. `tags` are the person's tags, comma separated, kept by the server
 *  each trimmed and lower-cased, repeats dropped; blank, none. */
type Values = { name: string; grade: string; gradeFrom: string; terms: string; termsFrom: string; contact: string; tags: string };
const EMPTY: Values = { name: '', grade: 'A', gradeFrom: '', terms: '', termsFrom: '', contact: '', tags: '' };

/** The form's values for a person as stored. */
const valuesOf = (p: Person): Values => ({
  name: p.name,
  grade: p.grade,
  gradeFrom: '',
  terms: p.terms === null ? '' : String(p.terms),
  termsFrom: '',
  contact: p.contact ?? '',
  tags: (p.tags ?? []).join(', '),
});

type Quick = { name: string; amount: string };
const NO_QUICK: Quick = { name: '', amount: '' };

/** The quick-add bar: a DRAFT claim of the amount, dated the sheet's today with an empty note, for the person with the
 *  name (case and outer spaces ignored); a name not on the sheet adds the person, grade A, first. The server does it as
 *  one change, so a refused claim adds no person. */
function QuickAdd({ sheetId, user }: { sheetId: string; user: string }) {
  const queryClient = useQueryClient();
  const [values, setValues] = useState<Quick>(NO_QUICK);
  const submit = useSubmitOnce();
  const add = useMutation({
    mutationFn: (v: Quick) =>
      postJson<Claim>(`/api/sheets/${encodeURIComponent(sheetId)}/quick-add`, { ...v, by: user }),
    onSuccess: () => {
      setValues(NO_QUICK);
      void queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) });
      void queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
    },
    onSettled: submit.end,
  });
  const change = (v: Partial<Quick>) => {
    setValues((was) => ({ ...was, ...v }));
    add.reset();
  };

  return (
    <form
      data-testid="quick-add"
      onSubmit={(e) => {
        e.preventDefault();
        if (!submit.begin()) return;
        add.reset();
        add.mutate(values);
      }}
    >
      Quick add{' '}
      <input data-testid="quick-name" placeholder="Name" value={values.name} onChange={(e) => change({ name: e.target.value })} />{' '}
      <input
        data-testid="quick-amount"
        placeholder="Amount"
        inputMode="decimal"
        value={values.amount}
        onChange={(e) => change({ amount: e.target.value })}
      />{' '}
      <button type="submit" data-testid="quick-submit" disabled={add.isPending}>
        Add draft claim
      </button>
      {add.isError && (
        <span data-testid="quick-error">
          {' '}
          {values.name.trim() === ''
            ? 'A name is required.'
            : "The amount must be 0.00 or more, with up to two decimals, its due-by not inside a closed period, and not after the person's retirement date."}
        </span>
      )}
    </form>
  );
}

/** The sheet's people: a form that adds a person or saves the one being edited, and the list. The editor
